// newItemsLookupCmd resolves a UPC/EAN through AnyList's product catalog. It
// is intentionally read-only: callers can inspect the result, then pass the
// barcode to items add so AnyList receives the identifier first.
func newItemsLookupCmd(flags *rootFlags) *cobra.Command {
	var barcode string

	cmd := &cobra.Command{
		Use:     "lookup",
		Short:   "Look up product details by UPC/EAN barcode",
		Example: "  anylist-pp-cli items lookup --barcode 049000028904 --json",
		Annotations: map[string]string{
			"pp:endpoint":   "items.lookup",
			"pp:method":     "GET",
			"pp:path":       "/data/product-lookup/{barcode}",
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if barcode == "" && len(args) > 0 {
				barcode = args[0]
			}
			if barcode == "" && !flags.dryRun {
				return fmt.Errorf("required flag \"barcode\" not set")
			}
			if dryRunOK(flags) {
				return nil
			}

			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}
			if cfg.AccessToken == "" {
				return authErr(fmt.Errorf("not authenticated — run 'anylist-pp-cli auth login' first"))
			}

			result, err := anylist.New(cfg).ProductLookup(cmd.Context(), barcode)
			if err != nil {
				return err
			}
			item := result.GetListItem()
			if item == nil {
				return fmt.Errorf("AnyList returned no product for barcode %q", barcode)
			}

			packageSize := formatPackageSize(item.GetPackageSizePb())
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"barcode":         item.GetProductUpc(),
					"name":            item.GetName(),
					"quantity":        item.GetQuantity(),
					"quantity_detail": item.GetQuantityPb(),
					"package_size":    packageSize,
					"package_detail":  item.GetPackageSizePb(),
					"details":         item.GetDetails(),
					"category":        item.GetCategory(),
					"thumbnail_url":   result.GetProductThumbnailUrl(),
					"prices":          item.GetPrices(),
				}, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "NAME\t%s\n", item.GetName())
			fmt.Fprintf(cmd.OutOrStdout(), "BARCODE\t%s\n", item.GetProductUpc())
			fmt.Fprintf(cmd.OutOrStdout(), "QUANTITY\t%s\n", item.GetQuantity())
			fmt.Fprintf(cmd.OutOrStdout(), "PACKAGE_SIZE\t%s\n", packageSize)
			fmt.Fprintf(cmd.OutOrStdout(), "CATEGORY\t%s\n", item.GetCategory())
			fmt.Fprintf(cmd.OutOrStdout(), "THUMBNAIL_URL\t%s\n", result.GetProductThumbnailUrl())
			return nil
		},
	}

	cmd.Flags().StringVar(&barcode, "barcode", "", "UPC/EAN barcode")
	cmd.Flags().StringVar(&barcode, "upc", "", "Alias for --barcode")
	return cmd
}

func formatPackageSize(size *pb.PBItemPackageSize) string {
	if size == nil {
		return ""
	}
	if raw := strings.TrimSpace(size.GetRawPackageSize()); raw != "" {
		return raw
	}
	parts := make([]string, 0, 2)
	if v := strings.TrimSpace(size.GetSize()); v != "" {
		parts = append(parts, v)
	}
	if v := strings.TrimSpace(size.GetUnit()); v != "" {
		parts = append(parts, v)
	}
	if v := strings.TrimSpace(size.GetPackageType()); v != "" {
		parts = append(parts, v)
	}
	return strings.Join(parts, " ")
}
